insert into jj_collect.catalog(id,data) values('nu-451','{"id": "nu-451", "number": 451, "name_es": "Jesús · despertar azul plateado", "name_en": "Jesús · Blue Silver Awakening", "character": "jesus", "theme": "fantasia", "tags": ["soul-land-i"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Un comienzo pequeño también puede abrirnos un mundo entero por descubrir juntos.", "dedication_en": "A small beginning can open a whole world for us to discover together.", "art": 0, "collection": "decimosexto-universo"}'::jsonb) on conflict(id) do nothing;
